def kanonischer_text(wert):
    """Locale-unabhängiger Schlüssel für fachliche Textvergleiche."""
    text = str(wert or "")
    if text.isascii():
        return " ".join(text.lower().split())
    text = unicodedata.normalize("NFKD", text).replace("ß", "ss")
    text = "".join(zeichen for zeichen in text
                   if not unicodedata.combining(zeichen)).lower()
    return " ".join(text.split())

antwort_begrenzt_lesen:
def antwort_begrenzt_lesen(antwort, grenze, meldung):
    """Begrenzt HTTP-Antworten mit und ohne verlässliche Längenangabe."""
    try:
        angabe = antwort.headers.get("Content-Length")
        if angabe is not None and int(str(angabe).strip()) > grenze:
            raise GroessenFehler(meldung)
    except (AttributeError, TypeError, ValueError):
        pass
    teile = []
    uebrig = grenze + 1
    while uebrig:
        teil = antwort.read(min(64 * 1024, uebrig))
        if not teil:
            break
        teile.append(teil)
        uebrig -= len(teil)
    roh = b"".join(teile)
    if len(roh) > grenze:
        raise GroessenFehler(meldung)
    return roh

_text_dekodieren:
def _text_dekodieren(rohbytes):
    """Bytes einer Austauschdatei möglichst verlustfrei zu Text machen."""
    if rohbytes.startswith((b"\xff\xfe", b"\xfe\xff")):
        return rohbytes.decode("utf-16")
    for zeichensatz in ("utf-8-sig", "utf-8", "cp1252"):
        try:
            return rohbytes.decode(zeichensatz)
        except UnicodeDecodeError:
            continue
    return rohbytes.decode("latin-1", "replace")

_ist_iso:
def _ist_iso(text):
    """Prüft ein Datum der Form JJJJ-MM-TT auf Form und Gültigkeit."""
    if not isinstance(text, str) or not _ISO_DATUM.match(text):
        return False
    try:
        if text.isascii():
            datetime.fromisoformat(text)
        else:
            datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        return False
    return True

